(function ($) {

    'use strict';

    $(document.body).on('wc_fragments_refreshed', function () {

        const offcanvas = document.getElementById('wooshop-mini-cart');

        let bootstrap;
        if (offcanvas && typeof bootstrap !== 'undefined') {
            bootstrap.Offcanvas.getOrCreateInstance(offcanvas);
        }
    });

})(jQuery);